CREATE TABLE IF NOT EXISTS folder_cache_revisions(organization_id TEXT PRIMARY KEY NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, revision TEXT NOT NULL);
INSERT OR IGNORE INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations;
CREATE TRIGGER IF NOT EXISTS folder_cache_folders_insert AFTER INSERT ON folders BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (NEW.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_folders_update AFTER UPDATE ON folders BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (OLD.organization_id, NEW.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_folders_delete AFTER DELETE ON folders BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (OLD.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_files_insert AFTER INSERT ON documents BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (NEW.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_files_update AFTER UPDATE OF organization_id,home_folder_id,current_version_id,is_deleted,updated_at ON documents BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (OLD.organization_id, NEW.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_files_delete AFTER DELETE ON documents BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (OLD.organization_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_sizes_insert AFTER INSERT ON versions BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM documents WHERE id=NEW.document_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_sizes_update AFTER UPDATE OF size,document_id,id ON versions BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM documents WHERE id=OLD.document_id UNION SELECT organization_id FROM documents WHERE id=NEW.document_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_sizes_delete AFTER DELETE ON versions BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM documents WHERE id=OLD.document_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_shortcuts_insert AFTER INSERT ON document_shortcuts BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=NEW.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_shortcuts_update AFTER UPDATE OF folder_id,document_id ON document_shortcuts BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=OLD.folder_id UNION SELECT organization_id FROM folders WHERE id=NEW.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_shortcuts_delete AFTER DELETE ON document_shortcuts BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=OLD.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_grants_insert AFTER INSERT ON folder_acl BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=NEW.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_grants_update AFTER UPDATE ON folder_acl BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=OLD.folder_id UNION SELECT organization_id FROM folders WHERE id=NEW.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS folder_cache_grants_delete AFTER DELETE ON folder_acl BEGIN INSERT INTO folder_cache_revisions(organization_id,revision) SELECT id,lower(hex(randomblob(16))) FROM organizations WHERE id IN (SELECT organization_id FROM folders WHERE id=OLD.folder_id) ON CONFLICT(organization_id) DO UPDATE SET revision=excluded.revision; END;
